const sha=String(process.env.PREVIEW_SHA||'').trim();assert.match(sha,/^[0-9a-f]{40}$/);const path='preview/tournament-16/index21543.html';const raw=`https://raw.githubusercontent.com/yo666ha-boop/-/${sha}/${path}`,blob=`https://github.com/yo666ha-boop/-/blob/${sha}/${path}`,candidates=[`https://htmlpreview.github.io/?${raw}`,`https://htmlpreview.github.io/?${blob}`];
