 async function verifyGeometry(p,label){const g=await p.evaluate(()=>{const rs=[...document.querySelectorAll('.round')];let checks=0,errors=0,max=0;for(let r=0;r<Math.min(4,rs.length-1);r++){const src=[...rs[r].querySelectorAll('.slot')],dst=[...rs[r+1].querySelectorAll('.slot')];for(let i=0;i<dst.length;i++){const a=src[i*2],b=src[i*2+1],d=dst[i];if(!a||!b||!d)continue;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect(),dr=d.getBoundingClientRect(),expected=((ar.top+ar.bottom)/2+(br.top+br.bottom)/2)/2,actual=(dr.top+dr.bottom)/2,err=Math.abs(expected-actual);checks++;max=Math.max(max,err);if(err>1.25)errors++}}return{checks,errors,max:Number(max.toFixed(3))}});assert.equal(g.checks,15,`${label} checks`);assert.equal(g.errors,0,`${label} drift`);assert.ok(g.max<=1.25);return g}
 const openingGeometry=await verifyGeometry(page,'mobile opening');
