 audit=await page.evaluate(()=>window.TOURNAMENT_PREVIEW_AUDIT());assert.equal(audit.bossStatus,'pending');assert.equal(audit.tournamentChampion,true);assert.equal(audit.cupClear,false);assert.equal(audit.bossInBracket,false);assert.match(await page.locator('#status').innerText(),/トーナメント優勝/);assert.ok(await page.locator('#bossChallengeBtn21546:not([hidden])').count());assert.match(await page.locator('#bossPreview21546').innerText(),/トーナメントには参加せず/);
 const finalBracketAudit=await page.evaluate(()=>window.AI_SHOGI_TOURNAMENT_BRACKET_UI.audit());assert.equal(finalBracketAudit.pairingErrors,0);assert.equal(finalBracketAudit.invalidWins,0);assert.equal(finalBracketAudit.alignmentErrors,0);
