 console.log('PASS_TOURNAMENT_STANDALONE_PREVIEW_21546A '+JSON.stringify({url,status,cups:8,portraitCatalog:26,firstRoundPortraits:15,bossInBracket:false,tournamentWins:4,bossMatch:5,cupClear:true,initialRunning:7,initialResolved:0,fireOverflow:fireAudit.bracketOverflow,connectors:fireBracket.connectors,pairingErrors:finalBracketAudit.pairingErrors,mobileMaxAlignmentError:openingGeometry.max,fireMaxAlignmentError:fireGeometry.max}));
